/* R1969: personalized A4 walk-in poster. No changes to the existing order flow. */
(()=>{'use strict';
const PANEL='.walkinLinkCard', ID='pbWalkinPosterR1969';
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const validHttps=value=>{try{const url=new URL(String(value));return url.protocol==='https:'?url:null}catch{return null}};
async function json(path){const response=await fetch(path,{credentials:'same-origin',headers:{accept:'application/json'},cache:'no-store'});if(!response.ok)throw new Error('api_error');return response.json()}
function getLink(panel){return validHttps(panel.querySelector('.walkinLinkInfo input[readonly]')?.value||panel.querySelector('.walkinLinkInfo input')?.value)}
function documentHtml({labName,walkinUrl,siteUrl}){
 const name=escapeHtml(labName);
 const qr='https://api.qrserver.com/v1/create-qr-code/?size=900x900&margin=24&data='+encodeURIComponent(walkinUrl);
 const site=siteUrl?escapeHtml(new URL(siteUrl).hostname):'';
 const website=siteUrl?"<section class=\"website-section\" aria-label=\"ورود به سایت لابراتوار\"><div class=\"short-rule\" aria-hidden=\"true\"></div><h2 class=\"website-title\">ورود به سایت</h2><div class=\"website-address\" dir=\"ltr\">__SITE__</div><p class=\"hint\">از طریق سایت، عکس‌ها را ارسال کن.</p></section>".replaceAll('__SITE__',site):'';
 return "<!doctype html>\n<html lang=\"fa\" dir=\"rtl\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>پوستر ارسال عکس - __NAME__</title>\n<style>\n@font-face{font-family:PBVazirmatn;src:url('/assets/photobridge-handover-vazirmatn.woff2') format('woff2');font-style:normal;font-weight:100 900;font-display:swap}\n@page{size:A4 portrait;margin:0}\n*{box-sizing:border-box}\nhtml,body{margin:0;padding:0;background:white;color:#101114}\nbody{font-family:PBVazirmatn,Tahoma,Arial,sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact}\n.page{width:210mm;height:297mm;min-height:297mm;margin:auto;padding:11mm 18mm 9mm;display:flex;flex-direction:column;align-items:center;text-align:center;overflow:hidden;background:#fff}\n.brand{display:flex;align-items:center;justify-content:center;direction:rtl;gap:3.8mm;font-size:16pt;font-weight:850;line-height:1.6;color:#101114;max-width:100%;overflow-wrap:anywhere}\n.brand svg{width:11mm;height:11mm;flex:none;color:#1568b6}\n.brand .brand-line{height:9mm;border-right:.65mm solid #186cbe}\n.headline{margin:7mm 0 0;font-size:30pt;line-height:1.53;font-weight:900;letter-spacing:-.2mm;color:#0b0c10}\n.intro{margin:3mm 0 0;font-size:11.5pt;line-height:1.9;color:#30353c}\n.short-rule{width:21mm;height:.7mm;background:#0a6cc5;border-radius:5mm;flex:none}\n.head-rule{margin-top:5mm}\n.qr-area{display:flex;align-items:center;flex-direction:column;margin-top:7mm}\n.qr-frame{width:72mm;height:72mm;display:grid;place-items:center;position:relative;padding:4.5mm}\n.qr-image{width:63mm;height:63mm;display:block;background:white;object-fit:contain}\n.qr-corner{position:absolute;width:11mm;height:11mm;border:1.5mm solid #136dc5;border-radius:3mm;pointer-events:none}\n.qr-corner.tr{top:0;right:0;border-left:0;border-bottom:0;border-bottom-right-radius:0;border-top-left-radius:0}\n.qr-corner.tl{top:0;left:0;border-right:0;border-bottom:0;border-bottom-left-radius:0;border-top-right-radius:0}\n.qr-corner.br{bottom:0;right:0;border-left:0;border-top:0;border-top-right-radius:0;border-bottom-left-radius:0}\n.qr-corner.bl{bottom:0;left:0;border-right:0;border-top:0;border-top-left-radius:0;border-bottom-right-radius:0}\n.qr-title{margin:2mm 0 0;color:#0868bd;font-size:18pt;font-weight:850;line-height:1.5}\n.hint{margin:1mm 0 0;color:#34393f;font-size:10.5pt;line-height:1.8}\n.website-section{width:100%;display:flex;flex-direction:column;align-items:center;margin-top:6.5mm}\n.website-section .short-rule{margin-bottom:4mm}\n.website-title{font-size:18pt;font-weight:850;color:#0868bd;line-height:1.45}\n.website-address{font-family:Arial,Helvetica,sans-serif;font-size:18pt;font-weight:800;line-height:1.35;direction:ltr;unicode-bidi:isolate;background:#176fbe;color:white;padding:2.6mm 9mm;min-width:100mm;max-width:170mm;border-radius:20mm;margin:3mm 0 0;overflow-wrap:anywhere}\n.website-section .hint{margin-top:3mm}\n.process{width:100%;display:flex;align-items:center;justify-content:space-between;direction:rtl;margin-top:auto;padding:5mm 1mm 0}\n.step{display:flex;flex-direction:column;align-items:center;justify-content:center;min-width:36mm;max-width:49mm;gap:1.7mm;font-size:11pt;font-weight:850;color:#101114;line-height:1.7}\n.step svg{width:14mm;height:14mm;stroke:#1567b5;stroke-width:2.2;fill:none;stroke-linejoin:round;stroke-linecap:round}\n.chevron{color:#69a4d7;font-size:26pt;font-family:Arial,sans-serif;font-weight:400;line-height:1}\n.footer{width:100%;margin-top:6mm;display:flex;align-items:center;gap:4mm;color:#111319;font-size:13pt;font-weight:850;justify-content:center;line-height:1.7;overflow-wrap:anywhere}\n.footer:before,.footer:after{content:\"\";height:.6mm;background:#166bbc;flex:1;max-width:38mm}\n.onlyqr .qr-area{margin-top:18mm}\n.onlyqr .qr-frame{width:82mm;height:82mm;padding:5mm}\n.onlyqr .qr-image{width:72mm;height:72mm}\n.onlyqr .process{margin-top:auto}\n.print-error{background:#fff2f2;border:1px solid #b42318;color:#b42318;padding:4mm 6mm;font:12pt Tahoma,sans-serif;position:fixed;top:5mm;right:5mm;left:5mm;z-index:2}\n@media screen{body{background:#eef2f6}.page{box-shadow:0 3mm 10mm #182b3d22}}\n@media print{body{background:white}.page{box-shadow:none}.print-error{display:none!important}}\n</style></head>\n<body><div class=\"print-error\" id=\"qr-error\" hidden>بارگذاری QR انجام نشد. لطفاً اتصال اینترنت را بررسی و دوباره تلاش کنید؛ بدون QR پوستر را چاپ نکنید.</div>\n<main class=\"page __PAGE_CLASS__\">\n<header class=\"brand\"><svg viewBox=\"0 0 48 48\" aria-hidden=\"true\"><path d=\"M8 14h8l3-5h11l3 5h7a4 4 0 0 1 4 4v19a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4V18a4 4 0 0 1 4-4Z\" stroke=\"currentColor\" fill=\"none\" stroke-width=\"3.3\" stroke-linejoin=\"round\"/><circle cx=\"24\" cy=\"27\" r=\"8\" stroke=\"currentColor\" stroke-width=\"3.3\" fill=\"none\"/></svg><span class=\"brand-line\" aria-hidden=\"true\"></span><span>__NAME__</span></header>\n<h1 class=\"headline\">عکس‌هات رو همین‌جا<br>برای چاپ بفرست!</h1>\n<div class=\"short-rule head-rule\" aria-hidden=\"true\"></div>\n<p class=\"intro\">عکس‌هات رو برای چاپ، با موبایل برای ما ارسال کن</p>\n<section class=\"qr-area\" aria-label=\"ارسال عکس با اسکن QR\">\n<div class=\"qr-frame\"><img class=\"qr-image\" alt=\"کد QR اختصاصی ارسال عکس به لابراتوار\" src=\"__QR__\"><span class=\"qr-corner tr\"></span><span class=\"qr-corner tl\"></span><span class=\"qr-corner br\"></span><span class=\"qr-corner bl\"></span></div>\n<h2 class=\"qr-title\">اسکن QR</h2>\n<p class=\"hint\">کد را اسکن کن و سفارش را ثبت کن.</p>\n</section>\n__SITE_SECTION__\n<div class=\"process\" aria-label=\"مراحل ثبت سفارش\">\n<div class=\"step\"><svg viewBox=\"0 0 48 48\" aria-hidden=\"true\"><rect x=\"14\" y=\"4\" width=\"20\" height=\"40\" rx=\"4\"/><path d=\"M21 10h6M21 37h6M19 21h10v9H19z\" stroke-dasharray=\"2 3\"/></svg><span>اسکن / ورود</span></div>\n<span class=\"chevron\" aria-hidden=\"true\">‹</span>\n<div class=\"step\"><svg viewBox=\"0 0 48 48\" aria-hidden=\"true\"><rect x=\"10\" y=\"11\" width=\"31\" height=\"29\" rx=\"2\"/><path d=\"M6 35V7h31M12 34l8-9 8 6 6-8 6 10\"/><circle cx=\"31\" cy=\"18\" r=\"2\"/></svg><span>انتخاب عکس</span></div>\n<span class=\"chevron\" aria-hidden=\"true\">‹</span>\n<div class=\"step\"><svg viewBox=\"0 0 48 48\" aria-hidden=\"true\"><path d=\"M3 9h6l5 23h24l5-16H12M15 40h1M36 40h1\"/><circle cx=\"15\" cy=\"40\" r=\"2\"/><circle cx=\"36\" cy=\"40\" r=\"2\"/><circle cx=\"32\" cy=\"11\" r=\"8\"/><path d=\"m28 11 3 3 5-6\"/></svg><span>ثبت سفارش</span></div>\n</div>\n<footer class=\"footer\">__NAME__</footer>\n</main>\n<script>\nwindow.addEventListener('load',()=>{\n const qr=document.querySelector('.qr-image');\n const fail=()=>{document.querySelector('#qr-error').hidden=false};\n const print=()=>{if(!qr.naturalWidth){fail();return}setTimeout(()=>window.print(),300)};\n const fontReady=document.fonts&&document.fonts.ready?document.fonts.ready:Promise.resolve();\n Promise.all([fontReady,qr.decode?qr.decode():Promise.resolve()]).then(print).catch(fail);\n},{once:true});\n</script></body></html>"
  .replaceAll('__QR__',escapeHtml(qr))
  .replaceAll('__SITE_SECTION__',website)
  .replaceAll('__PAGE_CLASS__',siteUrl?'':'onlyqr')
  .replaceAll('__NAME__',name);
}

async function openPoster(button,panel){
 const url=getLink(panel);if(!url){alert('ابتدا لینک معتبر مشتری آزاد را فعال کنید.');return}
 button.disabled=true;const label=button.textContent;button.textContent='در حال آماده‌سازی پوستر…';
 // Open synchronously on user gesture to avoid popup blockers.
 const popup=window.open('','_blank');if(!popup){button.disabled=false;button.textContent=label;alert('اجازه باز کردن پنجره چاپ را در مرورگر فعال کنید.');return}
 try{
  const state=await json('/api/lab/walkin');const name=String(state?.lab?.name||'').trim();
  if(!name||!state?.url||validHttps(state.url)?.href!==url.href)throw new Error('invalid_walkin_state');
  let site=null;
  try{
   const info=await json('/api/lab/site');
   const domain=Array.isArray(info.domains)?info.domains.find(d=>d.active===true&&/^[a-z0-9.-]+$/i.test(d.hostname||'')):null;
   if(domain)site='https://'+domain.hostname+'/';
  }catch{/* Site feature may be unavailable: never invent a domain. */}
  popup.document.open();popup.document.write(documentHtml({labName:name,walkinUrl:url.href,siteUrl:site}));popup.document.close();
 }catch{popup.close();alert('ساخت پوستر انجام نشد. لطفاً صفحه را تازه‌سازی و دوباره تلاش کنید.')}
 finally{button.disabled=false;button.textContent=label}
}
function attach(){
 if(!location.pathname.startsWith('/lab/'))return;
 const panel=document.querySelector(PANEL);if(!panel||panel.querySelector('#'+ID))return;
 const actions=panel.querySelector('.walkinLinkActions');if(!actions||!getLink(panel))return;
 const button=document.createElement('button');button.id=ID;button.type='button';button.className='pbActionButton secondary';button.textContent='چاپ / ذخیره PDF پوستر A4';button.setAttribute('aria-label','چاپ یا ذخیره PDF پوستر اختصاصی مشتری آزاد');
 button.addEventListener('click',()=>openPoster(button,panel));actions.append(button);
}
let pending=false;const observer=new MutationObserver(()=>{if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;attach()})});
function start(){observer.observe(document.body,{childList:true,subtree:true});attach()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();